import {notFound} from 'next/navigation';import {requireVendor} from '@/lib/auth/vendor';import {fcfa,getVendorOrder,vendorStatusLabels} from '@/services/vendor-dashboard';import {updateOrderStatus} from '@/app/vendor/actions';import {SubmitButton,VendorFlash} from '@/components/vendor-forms';
const nextActions:Record<string,Array<{status:string;label:string;danger?:boolean}>>={pending:[{status:'confirmed',label:'Confirmer'},{status:'cancelled',label:'Annuler',danger:true}],confirmed:[{status:'preparing',label:'Commencer la préparation'},{status:'cancelled',label:'Annuler',danger:true}],preparing:[{status:'ready',label:'Marquer prête'},{status:'ready_for_pickup',label:'Prête pour retrait'},{status:'cancelled',label:'Annuler',danger:true}],ready:[{status:'out_for_delivery',label:'Mettre en livraison'}],ready_for_pickup:[{status:'collected',label:'Remise au client'}],out_for_delivery:[{status:'delivered',label:'Marquer livrée'}]};
export default async function OrderDetailPage({params,searchParams}:{params:Promise<{id:string}>;searchParams:Promise<{updated?:string;error?:string}>}){const[{id},query,context]=await Promise.all([params,searchParams,requireVendor()]);const row=await getVendorOrder(context.restaurant!.id,id);if(!row)notFound();const order=row.order as unknown as Record<string,unknown>;const items=(row.items??[]) as Array<Record<string,unknown>>;const fulfillment=String(order.fulfillment);const actions=(nextActions[row.status]??[]).filter(action=>!(action.status==='ready'&&fulfillment==='pickup')&&!(action.status==='ready_for_pickup'&&fulfillment==='delivery'));return <><VendorFlash message={query.error?'La commande n’a pas pu être mise à jour.':query.updated?'Commande mise à jour.':undefined}/><div className="vendor-page-head"><div><p className="section-kicker">Commande</p><h1>{String(order.reference)}</h1><p>{new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(String(order.created_at)))}</p></div><span className={`vendor-badge ${row.status}`}>{vendorStatusLabels[row.status]}</span></div><div className="vendor-order-detail"><section className="vendor-card"><h2>Produits</h2>{items.map(item=><article className="vendor-order-item" key={String(item.id)}><span><strong>{Number(item.quantity)} × {String(item.product_name)}</strong><small>{Array.isArray(item.options)&&item.options.length?`${item.options.length} option(s)`:''}</small></span><b>{fcfa(Number(item.line_total))}</b></article>)}<div className="order-total"><span>Total du restaurant</span><strong>{fcfa(row.subtotal+row.delivery_fee)}</strong></div></section><aside><section className="vendor-card customer-summary"><h2>Client</h2><dl><div><dt>Nom</dt><dd>{String(order.customer_name)}</dd></div><div><dt>Téléphone</dt><dd><a href={`tel:${String(order.customer_phone)}`}>{String(order.customer_phone)}</a></dd></div><div><dt>Livraison / retrait</dt><dd>{fulfillment==='pickup'?'Retrait':'Livraison'}</dd></div>{fulfillment==='delivery'?<><div><dt>Adresse</dt><dd>{String(order.address??'Non précisée')}</dd></div><div><dt>Zone</dt><dd>{String(order.commune??'—')}</dd></div></>:null}<div><dt>Paiement</dt><dd>{String(order.payment_method)}</dd></div><div><dt>Note</dt><dd>{String(order.customer_note??'Aucune')}</dd></div></dl></section>{actions.length?<section className="vendor-card order-actions"><h2>Mettre à jour</h2>{actions.map(action=><form action={updateOrderStatus} key={action.status}><input type="hidden" name="order_id" value={row.id}/><input type="hidden" name="status" value={action.status}/><SubmitButton className={action.danger?'btn btn-danger':'btn btn-dark'} pendingLabel="Mise à jour…" confirmMessage={action.danger?'Annuler cette commande ?':undefined}>{action.label}</SubmitButton></form>)}</section>:null}</aside></div></>}
